// Validate the AI evaluation and attach the application data needed later.
const e = $input.first().json.output || {};
const app = $('Prepare Application').first().json;
const email = $('Current Application').first().json.Email || '';

const problems = [];

// 1) score must be a number between 0 and 100
let score = Number(e.score);
if (!Number.isFinite(score)) {
  problems.push('score is missing or not a number');
  score = null;
} else if (score < 0 || score > 100) {
  problems.push('score out of range 0-100: ' + score);
  score = null;
} else {
  score = Math.round(score);
}

// 2) recommendation must be one of the allowed values
const allowed = ['interview', 'maybe', 'reject'];
let recommendation = String(e.recommendation || '').trim().toLowerCase();
if (!allowed.includes(recommendation)) {
  problems.push('invalid recommendation: ' + (e.recommendation ?? 'missing'));
  recommendation = null;
}

// 3) the score decides: fix the recommendation if it does not match the score
let corrected = false;
if (score !== null) {
  const expected = score >= 70 ? 'interview' : score >= 40 ? 'maybe' : 'reject';
  if (recommendation && recommendation !== expected) corrected = true;
  recommendation = expected;
}

// 4) list fields must be arrays of non-empty strings
const toList = v => (Array.isArray(v) ? v : [])
  .map(x => String(x).trim())
  .filter(Boolean);

const interviewQuestions = toList(e.interview_questions);
if (recommendation === 'interview' && interviewQuestions.length === 0) {
  problems.push('interview_questions is empty for an interview recommendation');
}

return [{ json: {
  isValid: problems.length === 0,
  validationNote: problems.join('; '),
  correctedRecommendation: corrected,

  score,
  recommendation,
  matchedRequirements: toList(e.matched_requirements),
  missingRequirements: toList(e.missing_requirements),
  strengths: toList(e.strengths),
  concerns: toList(e.concerns),
  interviewQuestions,

  // application data for the next nodes (emails and sheet update)
  appliedAt: app['Applied At'],
  name: app.Name,
  position: app.Position,
  email,
  cvFileId: app['CV File ID'],
  readMethod: app['read method'],
} }];

