=<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Candidate Evaluation Report</title>
    <style>
        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            margin: 0;
            padding: 20px;
            background-color: #f8f9fa;
            color: #343a40;
        }
        .container {
            max-width: 800px;
            margin: 0 auto;
            background-color: #ffffff;
            border-radius: 12px;
            box-shadow: 0 4px 15px rgba(0,0,0,0.05);
            overflow: hidden;
        }
        .header {
            background-color: #163628;
            color: #ffffff;
            padding: 30px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }
        .header-title-area {
            display: flex;
            flex-direction: column;
        }
        .candidate-label {
            font-size: 14px;
            text-transform: uppercase;
            letter-spacing: 2px;
            opacity: 0.8;
            margin-bottom: 5px;
        }
        .candidate-name {
            font-size: 28px;
            font-weight: 700;
            margin: 0;
        }
        .score-display {
            background-color: #00bf8a;
            color: white;
            padding: 15px 25px;
            border-radius: 8px;
            text-align: center;
        }
        .score-value {
            font-size: 32px;
            font-weight: 800;
        }
        .score-total {
            font-size: 14px;
            opacity: 0.9;
        }
        .report-body {
            padding: 30px;
        }
        .info-card, .section-card {
            background-color: #fcfdfe;
            border: 1px solid #e1e7ec;
            border-radius: 10px;
            padding: 20px;
            margin-bottom: 25px;
        }
        .info-row {
            display: flex;
            margin-bottom: 12px;
            align-items: center;
        }
        .info-label {
            font-weight: bold;
            color: #2e3b4e;
            width: 140px;
            flex-shrink: 0;
        }
        .info-value {
            color: #4b5563;
        }
        .section-title {
            font-size: 18px;
            font-weight: bold;
            color: #163628;
            margin-top: 0;
            margin-bottom: 15px;
            border-bottom: 2px solid #e1e7ec;
            padding-bottom: 10px;
        }
        .strengths-text {
            line-height: 1.8;
            color: #1e7e34;
            margin: 0;
        }
        .concerns-text {
            line-height: 1.8;
            color: #d12e4c;
            margin: 0;
        }
        .question-item {
            background-color: #f1f3f5;
            padding: 15px;
            border-radius: 8px;
            margin-bottom: 15px;
            border-left: 4px solid #163628;
        }
        .question-text {
            color: #343a40;
            line-height: 1.6;
            margin: 0;
        }
        @media (max-width: 600px) {
            .header {
                flex-direction: column;
                text-align: center;
                gap: 15px;
            }
            .info-row {
                flex-direction: column;
                align-items: flex-start;
            }
            .info-label {
                width: 100%;
                margin-bottom: 5px;
            }
        }
    </style>
</head>
<body>

<div class="container">
    <!-- Header -->
    <div class="header">
        <div class="header-title-area">
            <span class="candidate-label">CANDIDATE EVALUATION REPORT</span>
            <h1 class="candidate-name">{{ $('Validate Evaluation').first().json.name }}</h1>
        </div>
        <div class="score-display">
            <div class="score-value">{{ $('Validate Evaluation').first().json.score }}</div>
            <div class="score-total">/100</div>
        </div>
    </div>

    <div class="report-body">
        <!-- Basic Information -->
        <div class="info-card">
            <div class="info-row">
                <div class="info-label">POSITION:</div>
                <div class="info-value">{{ $('Validate Evaluation').first().json.position }}</div>
            </div>
            <div class="info-row">
                <div class="info-label">EMAIL:</div>
                <div class="info-value">{{ $('Validate Evaluation').first().json.email }}</div>
            </div>
            <div class="info-row">
                <div class="info-label">matchedRequirements:</div>
                <div class="info-value">{{ $('Validate Evaluation').item.json.matchedRequirements }}</div>
            </div>
            <div class="info-row">
                <div class="info-label">missingRequirements:</div>
                <div class="info-value">{{ $('Validate Evaluation').item.json.missingRequirements }}</div>
            </div>
        </div>

        <!-- Strengths Section -->
        <div class="section-card">
            <h2 class="section-title">✨ Key Strengths</h2>
            <p class="strengths-text">
                {{ $('Validate Evaluation').first().json.strengths.join(', ') }}
            </p>
        </div>

        <!-- Concerns Section -->
        <div class="section-card">
            <h2 class="section-title">⚠️ Potential Areas for Growth</h2>
            <p class="concerns-text">
                {{ $('Validate Evaluation').first().json.concerns.join(', ') }}
            </p>
        </div>

        <!-- Interview Questions Section -->
        <div class="section-card">
            <h2 class="section-title">💡 Proactive Interview Questions</h2>
            <div class="questions-list">
                {{ $('Validate Evaluation').first().json.interviewQuestions.map(q => `<div class="question-item"><p class="question-text">${q}</p></div>`).join('') }}
            </div>
        </div>

    </div>
</div>

</body>
</html>
